    // === FIXED LAYOUT ===
    // SVG dimensions: wide enough for horizontal pipeline
    var W = 1200, H = 760;
    var nodeById = {};
    nodes.forEach(function(n) { nodeById[n.id] = n; });

    // Manual positions for a clean top-to-bottom+branching layout
    // Pipeline flows left-to-right in the center, version control at bottom-center
    var positions = {
