      'inference_online': { x: 880,  y: 190 },
      'inference_offline':{ x: 880,  y: 370 },
      'ab_experiment':    { x: 1060, y: 280 },
      'monitoring':       { x: 1060, y: 560 },
      'version_control':  { x: 510,  y: 560 }
    };
    nodes.forEach(function(n) {
