    }

    function buildDiagram() {
      var svg = d3.select('#diagram-svg')
        .attr('width', W)
        .attr('height', H)
        .attr('viewBox', '0 0 ' + W + ' ' + H);

      svg.selectAll('*').remove();

      var isDark = document.documentElement.classList.contains('theme-dark');
      var bgSurface = isDark ? '#141414' : '#ffffff';
      var textMain = isDark ? '#EDEDED' : '#0f172a';
      var textSec = isDark ? '#888' : '#64748b';
      var borderCol = isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.08)';

      // Background
      svg.append('rect').attr('width', W).attr('height', H).attr('fill', bgSurface);

      // Subtle layer band labels
      var bandData = [
        { x: 10, y: 0, w: 210, h: H, label: 'DATA', color: isDark ? 'rgba(59,130,246,0.04)' : 'rgba(37,99,235,0.04)' },
        { x: 220, y: 0, w: 380, h: H, label: 'COMPUTE', color: isDark ? 'rgba(16,185,129,0.04)' : 'rgba(5,150,105,0.04)' },
        { x: 600, y: 0, w: 390, h: H, label: 'SERVING', color: isDark ? 'rgba(249,115,22,0.04)' : 'rgba(234,88,12,0.04)' },
        { x: 990, y: 0, w: 210, h: H, label: 'OBSERVABILITY', color: isDark ? 'rgba(244,63,94,0.04)' : 'rgba(225,29,72,0.04)' }
      ];
      var bands = svg.append('g').attr('class', 'bands');
      bandData.forEach(function(b) {
        bands.append('rect')
          .attr('x', b.x).attr('y', b.y)
          .attr('width', b.w).attr('height', b.h)
          .attr('fill', b.color)
          .attr('rx', 0);
        bands.append('text')
          .attr('x', b.x + b.w / 2)
          .attr('y', 22)
          .attr('text-anchor', 'middle')
          .attr('fill', isDark ? 'rgba(255,255,255,0.15)' : 'rgba(0,0,0,0.15)')
          .attr('font-size', '10')
          .attr('font-weight', '600')
          .attr('letter-spacing', '0.1em')
          .attr('font-family', 'Inter, sans-serif')
          .text(b.label);
      });

      // === DEFS: arrowheads per flow type ===
      var defs = svg.append('defs');

      // Markers for each flow type + color variants
      var markerDefs = [
        { id: 'arrow-primary', color: isDark ? 'rgba(255,255,255,0.55)' : 'rgba(15,23,42,0.5)' },
        { id: 'arrow-feedback', color: isDark ? '#f59e0b' : '#d97706' },
        { id: 'arrow-lineage', color: isDark ? '#a78bfa' : '#7c3aed' }
      ];
      markerDefs.forEach(function(m) {
        defs.append('marker')
          .attr('id', m.id)
          .attr('viewBox', '0 0 10 10')
          .attr('refX', 9)
          .attr('refY', 5)
          .attr('markerWidth', 6)
          .attr('markerHeight', 6)
          .attr('orient', 'auto')
          .append('path')
          .attr('d', 'M 0 0 L 10 5 L 0 10 z')
          .attr('fill', m.color);
      });

      // Glow filters
