        { id: 'glow-data', color: isDark ? '#3b82f6' : '#2563eb' },
        { id: 'glow-compute', color: isDark ? '#10b981' : '#059669' },
        { id: 'glow-serving', color: isDark ? '#f97316' : '#ea580c' },
        { id: 'glow-obs', color: isDark ? '#f43f5e' : '#e11d48' },
        { id: 'glow-cross', color: isDark ? '#a78bfa' : '#7c3aed' }
      ];
      glowColors.forEach(function(g) {
        var filter = defs.append('filter').attr('id', g.id).attr('x', '-40%').attr('y', '-40%').attr('width', '180%').attr('height', '180%');
        filter.append('feGaussianBlur').attr('in', 'SourceGraphic').attr('stdDeviation', '8').attr('result', 'blur');
        var merge = filter.append('feMerge');
        merge.append('feMergeNode').attr('in', 'blur');
        merge.append('feMergeNode').attr('in', 'SourceGraphic');
      });

      // === Build edge lookup ===
      var edgeGroup = svg.append('g').attr('class', 'edges');
      var feedbackGroup = svg.append('g').attr('class', 'feedback-edges');
      var lineageGroup = svg.append('g').attr('class', 'lineage-edges');

      // Helper: compute edge path with offset to avoid node overlap
      function getEdgePath(src, tgt, offset) {
        offset = offset || 0;
        var dx = tgt.x - src.x;
        var dy = tgt.y - src.y;
        var len = Math.sqrt(dx * dx + dy * dy);
        var r1 = nodeRadius(src.criticality);
        var r2 = nodeRadius(tgt.criticality) + 4; // extra offset for arrowhead
        var sx = src.x + (dx / len) * r1;
        var sy = src.y + (dy / len) * r1;
        var ex = tgt.x - (dx / len) * r2;
        var ey = tgt.y - (dy / len) * r2;
        // Curved path for feedback/lineage
        if (offset !== 0) {
          var mx = (sx + ex) / 2 - (dy / len) * offset;
          var my = (sy + ey) / 2 + (dx / len) * offset;
          return 'M ' + sx + ' ' + sy + ' Q ' + mx + ' ' + my + ' ' + ex + ' ' + ey;
        }
        return 'M ' + sx + ' ' + sy + ' L ' + ex + ' ' + ey;
      }

      function getEdgeColor(flow_type) {
        if (flow_type === 'feedback') return isDark ? '#f59e0b' : '#d97706';
        if (flow_type === 'lineage') return isDark ? '#a78bfa' : '#7c3aed';
        return isDark ? 'rgba(255,255,255,0.45)' : 'rgba(15,23,42,0.4)';
      }

      // Draw edges
      edges.forEach(function(e) {
        var src = nodeById[e.source];
        var tgt = nodeById[e.target];
        if (!src || !tgt) return;

        var grp = (e.flow_type === 'feedback') ? feedbackGroup : (e.flow_type === 'lineage') ? lineageGroup : edgeGroup;
        var color = getEdgeColor(e.flow_type);
        var markerId = 'arrow-' + e.flow_type;
        var strokeW = e.flow_type === 'lineage' ? Math.max(1, edgeWidth(e.throughput_gbps) * 0.7) : edgeWidth(e.throughput_gbps);
        var strokeOpacity = e.flow_type === 'lineage' ? 0.6 : (e.flow_type === 'feedback' ? 0.8 : 0.7);
        var curvature = (e.flow_type === 'feedback') ? 90 : (e.flow_type === 'lineage') ? 60 : 0;

        // Some feedback/lineage edges need extra curvature to avoid overlap
        if (e.source === 'monitoring' && e.target === 'data_platform') curvature = 120;
        if (e.source === 'monitoring' && e.target === 'training_cluster') curvature = 80;
        if (e.source === 'data_platform' && e.target === 'version_control') curvature = -60;
        if (e.source === 'version_control' && e.target === 'feature_store') curvature = -50;
        if (e.source === 'version_control' && e.target === 'training_cluster') curvature = 0;
        if (e.source === 'version_control' && e.target === 'model_registry') curvature = 50;

        var pathD = getEdgePath(src, tgt, curvature);
