          my = my + (dx2/len2) * curvature * 0.45;
        }

        // Label for primary edges with significant throughput
        if (e.flow_type === 'primary' && e.throughput_gbps >= 1.5) {
          var labelGroup = grp.append('g').attr('transform', 'translate(' + mx + ',' + my + ')');
          labelGroup.append('rect')
            .attr('x', -28).attr('y', -9).attr('width', 56).attr('height', 16)
            .attr('fill', bgSurface).attr('rx', 4).attr('opacity', 0.85);
          labelGroup.append('text')
            .attr('text-anchor', 'middle').attr('dy', '0.35em')
            .attr('fill', textSec).attr('font-size', '10').attr('font-family', 'Inter, sans-serif')
            .attr('font-weight', '500')
            .text(e.throughput_gbps + ' Gbps');
        }
      });

      // === Draw Nodes ===
      var nodeGroup = svg.append('g').attr('class', 'nodes');

      nodes.forEach(function(n) {
        var r = nodeRadius(n.criticality);
        var color = (function() {
          if (currentTheme === 'light') {
