          }
          return layerColors[n.layer] || '#888';
        })();

        var glowId = { 'data': 'glow-data', 'compute': 'glow-compute', 'serving': 'glow-serving', 'observability': 'glow-obs', 'cross-cutting': 'glow-cross' }[n.layer] || 'glow-data';

        var g = nodeGroup.append('g')
          .attr('class', 'node-group')
          .attr('transform', 'translate(' + n.x + ',' + n.y + ')')
