          .attr('opacity', isDark ? 0.15 : 0.1)
          .attr('filter', 'url(#' + glowId + ')');

        // Main circle
        g.append('circle')
          .attr('r', r)
          .attr('fill', isDark ? 'rgba(20,20,20,0.9)' : 'rgba(255,255,255,0.95)')
          .attr('stroke', color)
          .attr('stroke-width', isDark ? 2 : 2)
          .attr('filter', null);

        // Inner fill circle
        g.append('circle')
          .attr('r', r - 4)
          .attr('fill', color)
          .attr('opacity', isDark ? 0.18 : 0.12);

        // Criticality ring accent
        g.append('circle')
          .attr('r', r)
          .attr('fill', 'none')
          .attr('stroke', color)
          .attr('stroke-width', 2)
          .attr('opacity', 0.9);

        // Node label - line 1
        g.append('text')
          .attr('text-anchor', 'middle')
          .attr('dy', n.sublabel ? '-0.55em' : '0.35em')
          .attr('fill', textMain)
          .attr('font-size', r > 38 ? '11' : '10')
          .attr('font-weight', '600')
          .attr('font-family', 'Inter, sans-serif')
          .text(n.label);

        // Node label - line 2 (sublabel)
        if (n.sublabel) {
          g.append('text')
            .attr('text-anchor', 'middle')
            .attr('dy', '0.8em')
            .attr('fill', textSec)
            .attr('font-size', '9')
            .attr('font-family', 'Inter, sans-serif')
            .text(n.sublabel);
        }

        // Criticality badge
        g.append('circle')
          .attr('cx', r * 0.7).attr('cy', -r * 0.7)
          .attr('r', 9)
          .attr('fill', color)
          .attr('opacity', 0.9);
        g.append('text')
          .attr('x', r * 0.7).attr('y', -r * 0.7)
          .attr('text-anchor', 'middle').attr('dy', '0.35em')
          .attr('fill', 'white')
          .attr('font-size', '8').attr('font-weight', '700')
          .attr('font-family', 'Inter, sans-serif')
          .text(n.criticality);

        // Hover interaction
        g.on('mouseover', function(event) {
          d3.select(this).select('circle:first-of-type')
            .transition().duration(150)
