          showTooltip(event, n, color);
        });
        g.on('mousemove', function(event) { moveTooltip(event); });
        g.on('mouseout', function() {
          d3.select(this).select('circle:first-of-type')
            .transition().duration(150)
            .attr('opacity', isDark ? 0.15 : 0.1);
          hideTooltip();
        });
        g.on('focus', function(event) { showTooltip(event, n, color); });
        g.on('blur', function() { hideTooltip(); });
      });

      // Feedback loop label
      svg.append('text')
        .attr('x', 590).attr('y', H - 15)
        .attr('text-anchor', 'middle')
        .attr('fill', isDark ? 'rgba(245,158,11,0.6)' : 'rgba(217,119,6,0.6)')
        .attr('font-size', '10').attr('font-weight', '500')
        .attr('font-family', 'Inter, sans-serif')
        .attr('letter-spacing', '0.06em')
        .text('⟳  CLOSED-LOOP FEEDBACK: Monitoring → Data Platform / Training Cluster');
    }

    // === Tooltip ===
    var tooltip = document.getElementById('tooltip');
    function showTooltip(event, n, color) {
      var chips = n.sub_components.map(function(s) { return '<span class="tooltip-chip">' + s + '</span>'; }).join('');
      tooltip.innerHTML =
        '<div class="tooltip-name" style="color:' + color + '">' + n.label + (n.sublabel ? ' ' + n.sublabel : '') + '</div>' +
        '<div class="tooltip-row"><span class="tooltip-label">Layer</span><span class="tooltip-value">' + n.layer + '</span></div>' +
        '<div class="tooltip-row"><span class="tooltip-label">Criticality</span><span class="tooltip-value">' + n.criticality + ' / 10</span></div>' +
        '<div class="tooltip-chips">' + chips + '</div>';
      moveTooltip(event);
      tooltip.classList.add('visible');
    }
    function moveTooltip(event) {
      var x = event.clientX + 16, y = event.clientY - 20;
      if (x + 280 > window.innerWidth) x = event.clientX - 280;
      if (y + 150 > window.innerHeight) y = event.clientY - 150;
      tooltip.style.left = x + 'px';
      tooltip.style.top = y + 'px';
    }
    function hideTooltip() { tooltip.classList.remove('visible'); }

    // === Theme-aware diagram rebuild ===
    function onThemeChange() { buildDiagram(); }

    // === Responsive SVG ===
    function resizeDiagram() {
      var container = document.getElementById('diagramContainer');
      var w = container.offsetWidth;
      var svgEl = document.getElementById('diagram-svg');
      var scale = Math.min(1, w / W);
      svgEl.style.height = (H * scale) + 'px';
    }

    // === Initialize ===
    document.addEventListener('DOMContentLoaded', function() {
      buildDiagram();
      resizeDiagram();
      window.addEventListener('resize', resizeDiagram);
    });
  </script>
</body>
