            <div class="legend-item">
              <span style="font-size:16px;width:24px;text-align:center;color:#10b981;font-weight:700;">②</span>
              <div><div class="legend-text">Training</div><div class="legend-sub">Feature Store → GPU Cluster → Registry</div></div>
            </div>
            <div class="legend-item">
              <span style="font-size:16px;width:24px;text-align:center;color:#f97316;font-weight:700;">③</span>
              <div><div class="legend-text">Serving (Branched)</div><div class="legend-sub">Online (RT) ⊕ Offline (Batch) → A/B</div></div>
            </div>
            <div class="legend-item">
              <span style="font-size:16px;width:24px;text-align:center;color:#f59e0b;font-weight:700;">④</span>
              <div><div class="legend-text">Feedback Loop</div><div class="legend-sub">Monitoring → Platform + Cluster (retrain)</div></div>
            </div>
          </div>
        </div>
      </div>
    </section>
  </main>

  <div class="tooltip-panel" id="tooltip" role="tooltip" aria-live="polite"></div>

  <script>
    // === MENU ===
    function toggleMenu() {
      var dd = document.getElementById('vizMenuDropdown');
      if (dd) dd.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.viz-menu')) {
        var dd = document.getElementById('vizMenuDropdown');
        if (dd) dd.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var dd = document.getElementById('vizMenuDropdown');
        if (dd) dd.classList.remove('open');
      }
    });

    // === THEME — applied early so diagram renders correctly ===
    var currentTheme = 'dark'; // default until localStorage read
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      var icon = document.getElementById('themeIcon');
      var label = document.getElementById('themeLabel');
      if (icon) icon.textContent = t === 'dark' ? '🌙' : '☀️';
      if (label) label.textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
    }
    function cycleTheme() {
      applyTheme(currentTheme === 'dark' ? 'light' : 'dark');
      buildDiagram();
    }
    // Read saved or OS preference
    var savedT = localStorage.getItem('viz-theme');
    currentTheme = savedT || (window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
    applyTheme(currentTheme);

    // === SCROLL REVEAL ===
    document.querySelectorAll('[data-reveal]').forEach(function(el) { el.classList.add('reveal'); });
    var revObs = new IntersectionObserver(function(entries) {
      entries.forEach(function(e) { if (e.isIntersecting) { e.target.classList.add('visible'); revObs.unobserve(e.target); } });
    }, { threshold: 0.15 });
    document.querySelectorAll('.reveal').forEach(function(el) { revObs.observe(el); });

    // === DOWNLOAD PNG ===
    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      if (menu) menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, { quality: 1, pixelRatio: 2 });
        var a = document.createElement('a'); a.href = url;
        a.download = 'ml-infrastructure-architecture.png'; a.click();
      } catch(err) { console.error('Download failed:', err); }
      if (menu) menu.style.display = '';
    }

    // === DIAGRAM DATA ===
    var NODES = [
      { id: 'data_platform', label: 'Data Platform', sublabel: '(Spark / Flink)', layer: 'data', criticality: 9, subs: ['Apache Spark', 'Apache Flink', 'Kafka Ingestion'] },
      { id: 'feature_store', label: 'Feature Store', sublabel: '', layer: 'data', criticality: 8, subs: ['Online Store (Redis)', 'Offline Store (Hive)', 'Feature Registry'] },
      { id: 'training_cluster', label: 'Training Cluster', sublabel: '(GPU)', layer: 'compute', criticality: 10, subs: ['NVIDIA A100 Pool', 'Distributed Training (Horovod)', 'Hyperparameter Tuning'] },
      { id: 'model_registry', label: 'Model Registry', sublabel: '', layer: 'compute', criticality: 8, subs: ['MLflow Registry', 'Model Versioning', 'Artifact Storage (S3)'] },
      { id: 'inference_online', label: 'Inference Service', sublabel: '(Online / Real-time)', layer: 'serving', criticality: 9, subs: ['TensorRT', 'Triton Server', 'Load Balancer'] },
      { id: 'inference_offline', label: 'Inference Service', sublabel: '(Offline / Batch)', layer: 'serving', criticality: 7, subs: ['Spark Batch Predict', 'Scheduled Jobs (Airflow)'] },
      { id: 'ab_experiment', label: 'A/B Experiment', sublabel: 'Platform', layer: 'serving', criticality: 8, subs: ['Traffic Splitting', 'Statistical Engine', 'Experiment Dashboard'] },
      { id: 'monitoring', label: 'Monitoring &', sublabel: 'Alerting', layer: 'observability', criticality: 9, subs: ['Prometheus', 'Grafana', 'PagerDuty', 'Data Drift Detector'] },
      { id: 'version_control', label: 'Version Control', sublabel: '& Data Lineage', layer: 'cross', criticality: 7, subs: ['DVC', 'Git', 'Lineage Graph DB'] }
    ];

    var EDGES = [
      { s: 'data_platform', t: 'feature_store', type: 'primary', gbps: 12.5, label: '12.5 Gbps' },
      { s: 'feature_store', t: 'training_cluster', type: 'primary', gbps: 8.0, label: '8.0 Gbps' },
      { s: 'training_cluster', t: 'model_registry', type: 'primary', gbps: 2.5, label: '2.5 Gbps' },
      { s: 'model_registry', t: 'inference_online', type: 'primary', gbps: 1.8, label: '1.8 Gbps' },
      { s: 'model_registry', t: 'inference_offline', type: 'primary', gbps: 3.2, label: '3.2 Gbps' },
      { s: 'inference_online', t: 'ab_experiment', type: 'primary', gbps: 5.0, label: '5.0 Gbps' },
      { s: 'inference_offline', t: 'ab_experiment', type: 'primary', gbps: 4.0, label: '4.0 Gbps' },
      { s: 'ab_experiment', t: 'monitoring', type: 'primary', gbps: 2.0, label: '2.0 Gbps' },
      { s: 'monitoring', t: 'data_platform', type: 'feedback', gbps: 0.5, label: 'Data Quality Alerts' },
      { s: 'monitoring', t: 'training_cluster', type: 'feedback', gbps: 0.3, label: 'Retrain Trigger' },
      { s: 'version_control', t: 'feature_store', type: 'lineage', gbps: 0.1, label: 'Feature Versioning' },
      { s: 'version_control', t: 'training_cluster', type: 'lineage', gbps: 0.1, label: 'Experiment Tracking' },
      { s: 'version_control', t: 'model_registry', type: 'lineage', gbps: 0.1, label: 'Model Lineage' },
      { s: 'data_platform', t: 'version_control', type: 'lineage', gbps: 0.2, label: 'Data Lineage' },
      { s: 'feature_store', t: 'inference_online', type: 'primary', gbps: 6.0, label: '6.0 Gbps' }
    ];

    // Node positions in a 1300 x 740 viewBox
    var POS = {
      'data_platform':    [120,  280],
      'feature_store':    [330,  280],
      'training_cluster': [560,  180],
      'model_registry':   [760,  280],
      'inference_online': [960,  180],
      'inference_offline':[960,  380],
      'ab_experiment':    [1160, 280],
      'monitoring':       [1160, 560],
      'version_control':  [560,  560]
    };
    var VW = 1300, VH = 680;

    // Colors per layer
    var DARK_COLORS = { data:'#3b82f6', compute:'#10b981', serving:'#f97316', observability:'#f43f5e', cross:'#a78bfa' };
    var LIGHT_COLORS = { data:'#2563eb', compute:'#059669', serving:'#ea580c', observability:'#e11d48', cross:'#7c3aed' };

    function layerColor(layer) {
      return currentTheme === 'dark' ? (DARK_COLORS[layer] || '#888') : (LIGHT_COLORS[layer] || '#888');
    }
    function nodeRadius(crit) { return 26 + (crit - 6) * 3.5; }
    function edgeWidth(gbps, type) {
      if (type === 'lineage') return 1.5;
      return Math.max(1.5, Math.min(6.5, 0.8 + gbps * 0.38));
    }

    // Build node lookup
    var nodeMap = {};
    NODES.forEach(function(n) {
      nodeMap[n.id] = n;
      n.x = POS[n.id][0];
      n.y = POS[n.id][1];
    });

    function buildDiagram() {
      var svg = d3.select('#diagram-svg');
      svg.selectAll('*').remove();

      var isDark = (currentTheme === 'dark');
      var bgCol = isDark ? '#141414' : '#ffffff';
      var textCol = isDark ? '#EDEDED' : '#0f172a';
      var textSecCol = isDark ? '#888888' : '#64748b';

      svg.attr('viewBox', '0 0 ' + VW + ' ' + VH)
         .attr('preserveAspectRatio', 'xMidYMid meet')
         .attr('height', VH)
         .attr('width', VW)
         .style('width', '100%')
         .style('height', 'auto');

      // BG
      svg.append('rect').attr('width', VW).attr('height', VH).attr('fill', bgCol);

      // Layer band backgrounds
      var bands = [
        { x1: 0,   x2: 228, col: isDark ? 'rgba(59,130,246,0.05)' : 'rgba(37,99,235,0.04)', label: 'DATA' },
        { x1: 228, x2: 650, col: isDark ? 'rgba(16,185,129,0.05)' : 'rgba(5,150,105,0.04)', label: 'COMPUTE' },
        { x1: 650, x2: 1050, col: isDark ? 'rgba(249,115,22,0.05)' : 'rgba(234,88,12,0.04)', label: 'SERVING' },
        { x1: 1050, x2: VW, col: isDark ? 'rgba(244,63,94,0.05)' : 'rgba(225,29,72,0.04)', label: 'OBSERVABILITY' }
      ];
      var bandG = svg.append('g');
      bands.forEach(function(b) {
        bandG.append('rect').attr('x', b.x1).attr('y', 0).attr('width', b.x2 - b.x1).attr('height', VH).attr('fill', b.col);
        bandG.append('text')
          .attr('x', (b.x1 + b.x2) / 2).attr('y', 16)
          .attr('text-anchor', 'middle')
          .attr('fill', isDark ? 'rgba(255,255,255,0.18)' : 'rgba(0,0,0,0.2)')
          .attr('font-size', 9).attr('font-weight', 600).attr('letter-spacing', '0.1em')
          .attr('font-family', 'Inter, sans-serif').text(b.label);
      });

      // Divider lines
      [228, 650, 1050].forEach(function(x) {
        svg.append('line').attr('x1', x).attr('y1', 0).attr('x2', x).attr('y2', VH)
          .attr('stroke', isDark ? 'rgba(255,255,255,0.04)' : 'rgba(0,0,0,0.06)')
          .attr('stroke-width', 1);
      });

      // === DEFS: arrowheads & glow ===
      var defs = svg.append('defs');
      var markers = [
        { id: 'arr-primary', col: isDark ? 'rgba(200,200,200,0.7)' : 'rgba(30,40,80,0.55)' },
        { id: 'arr-feedback', col: isDark ? '#f59e0b' : '#d97706' },
        { id: 'arr-lineage',  col: isDark ? '#a78bfa' : '#7c3aed' }
      ];
      markers.forEach(function(m) {
        defs.append('marker')
          .attr('id', m.id).attr('viewBox', '0 0 10 10')
          .attr('refX', 9).attr('refY', 5)
          .attr('markerWidth', 6).attr('markerHeight', 6)
          .attr('orient', 'auto')
          .append('path').attr('d', 'M0,0 L10,5 L0,10 z').attr('fill', m.col);
      });

      // Glow filters
      Object.keys(isDark ? DARK_COLORS : LIGHT_COLORS).forEach(function(layer) {
        var col = isDark ? DARK_COLORS[layer] : LIGHT_COLORS[layer];
        var f = defs.append('filter').attr('id', 'glow-' + layer)
          .attr('x', '-50%').attr('y', '-50%').attr('width', '200%').attr('height', '200%');
        f.append('feGaussianBlur').attr('in', 'SourceGraphic').attr('stdDeviation', 10).attr('result', 'blur');
        var merge = f.append('feMerge');
        merge.append('feMergeNode').attr('in', 'blur');
        merge.append('feMergeNode').attr('in', 'SourceGraphic');
      });

      // Helper: path between nodes avoiding circle boundary
      function edgePath(e) {
        var src = nodeMap[e.s], tgt = nodeMap[e.t];
        var dx = tgt.x - src.x, dy = tgt.y - src.y;
        var len = Math.sqrt(dx*dx + dy*dy);
        var r1 = nodeRadius(src.criticality) + 2;
        var r2 = nodeRadius(tgt.criticality) + 5;
        var sx = src.x + (dx/len)*r1, sy = src.y + (dy/len)*r1;
        var ex = tgt.x - (dx/len)*r2, ey = tgt.y - (dy/len)*r2;

        // Curvature for feedback/lineage/special paths
        var curve = 0;
        if (e.s === 'monitoring' && e.t === 'data_platform') curve = -130;
        else if (e.s === 'monitoring' && e.t === 'training_cluster') curve = -100;
        else if (e.s === 'data_platform' && e.t === 'version_control') curve = -60;
        else if (e.s === 'version_control' && e.t === 'feature_store') curve = 55;
        else if (e.s === 'version_control' && e.t === 'training_cluster') curve = -5;
        else if (e.s === 'version_control' && e.t === 'model_registry') curve = -55;
        else if (e.s === 'feature_store' && e.t === 'inference_online') curve = -65;
        else if (e.type === 'feedback') curve = -80;
        else if (e.type === 'lineage') curve = 40;

        if (curve !== 0) {
          var mx = (sx+ex)/2 + (dy/len)*curve*0.5;
          var my = (sy+ey)/2 - (dx/len)*curve*0.5;
          return 'M'+sx+','+sy+' Q'+mx+','+my+' '+ex+','+ey;
        }
        return 'M'+sx+','+sy+' L'+ex+','+ey;
      }

      // Edge midpoint for label
      function edgeMid(e) {
        var src = nodeMap[e.s], tgt = nodeMap[e.t];
        var dx = tgt.x - src.x, dy = tgt.y - src.y, len = Math.sqrt(dx*dx+dy*dy);
        var mx = (src.x+tgt.x)/2, my = (src.y+tgt.y)/2;
        var curve = 0;
        if (e.s === 'monitoring' && e.t === 'data_platform') curve = -130;
        else if (e.s === 'monitoring' && e.t === 'training_cluster') curve = -100;
        else if (e.s === 'data_platform' && e.t === 'version_control') curve = -60;
        else if (e.s === 'version_control' && e.t === 'feature_store') curve = 55;
        else if (e.s === 'version_control' && e.t === 'model_registry') curve = -55;
        else if (e.s === 'feature_store' && e.t === 'inference_online') curve = -65;
        else if (e.type === 'feedback') curve = -80;
        else if (e.type === 'lineage') curve = 40;
        if (curve !== 0) {
          mx = mx + (dy/len)*curve*0.25;
          my = my - (dx/len)*curve*0.25;
        }
        return [mx, my];
      }

      // Draw edges (primary first, then feedback, then lineage on top)
      var layerOrder = ['primary', 'feedback', 'lineage'];
      layerOrder.forEach(function(ftype) {
        var g = svg.append('g').attr('class', 'edge-layer-' + ftype);
        EDGES.filter(function(e) { return e.type === ftype; }).forEach(function(e) {
          var col = ftype === 'feedback' ? (isDark ? '#f59e0b' : '#d97706') :
                    ftype === 'lineage'  ? (isDark ? '#a78bfa' : '#7c3aed') :
                                           (isDark ? 'rgba(200,210,230,0.6)' : 'rgba(20,40,80,0.45)');
          var w = edgeWidth(e.gbps, ftype);
          var dash = ftype === 'primary' ? 'none' : ftype === 'feedback' ? '7 4' : '3 7';
          var opacity = ftype === 'lineage' ? 0.65 : (ftype === 'feedback' ? 0.85 : 0.75);

          g.append('path')
            .attr('d', edgePath(e))
            .attr('fill', 'none')
            .attr('stroke', col)
            .attr('stroke-width', w)
            .attr('stroke-opacity', opacity)
            .attr('stroke-dasharray', dash)
            .attr('stroke-linecap', 'round')
            .attr('marker-end', 'url(#arr-' + ftype + ')');

          // Labels for primary edges with notable throughput
          if (ftype === 'primary' && e.gbps >= 2.0) {
            var mid = edgeMid(e);
            var labelG = g.append('g').attr('transform', 'translate(' + mid[0] + ',' + mid[1] + ')');
            labelG.append('rect').attr('x', -26).attr('y', -9).attr('width', 52).attr('height', 16)
              .attr('rx', 4).attr('fill', bgCol).attr('opacity', 0.88);
            labelG.append('text').attr('text-anchor', 'middle').attr('dy', '0.35em')
              .attr('fill', textSecCol).attr('font-size', 9.5).attr('font-family', 'Inter, sans-serif')
              .attr('font-weight', 500).text(e.label);
          }
          // Labels for feedback
          if (ftype === 'feedback') {
            var mid2 = edgeMid(e);
            var fbG = g.append('g').attr('transform', 'translate(' + mid2[0] + ',' + mid2[1] + ')');
            fbG.append('rect').attr('x', -38).attr('y', -9).attr('width', 76).attr('height', 16)
              .attr('rx', 4).attr('fill', bgCol).attr('opacity', 0.88);
            fbG.append('text').attr('text-anchor', 'middle').attr('dy', '0.35em')
              .attr('fill', isDark ? '#f59e0b' : '#d97706').attr('font-size', 9).attr('font-family', 'Inter, sans-serif')
              .attr('font-weight', 600).text(e.label);
          }
        });
      });

      // === NODES ===
      var nodeG = svg.append('g').attr('class', 'nodes');
      NODES.forEach(function(n) {
        var r = nodeRadius(n.criticality);
        var col = layerColor(n.layer);
        var g = nodeG.append('g')
          .attr('class', 'node-group')
          .attr('transform', 'translate(' + n.x + ',' + n.y + ')')
          .attr('tabindex', 0)
          .attr('role', 'button')
          .attr('aria-label', n.label + ' ' + n.sublabel);

        // Glow halo
        g.append('circle').attr('r', r + 10).attr('fill', col)
          .attr('opacity', isDark ? 0.12 : 0.08)
          .attr('filter', 'url(#glow-' + n.layer + ')');

        // Outer ring
        g.append('circle').attr('r', r).attr('fill', 'none')
          .attr('stroke', col).attr('stroke-width', 2).attr('opacity', 0.85);

        // BG fill
        g.append('circle').attr('r', r - 1).attr('fill', bgCol);

        // Inner color fill
        g.append('circle').attr('r', r - 1).attr('fill', col)
          .attr('opacity', isDark ? 0.16 : 0.10);

        // Label line 1
        var hasSubl = (n.sublabel && n.sublabel.length > 0);
        g.append('text')
          .attr('text-anchor', 'middle').attr('dy', hasSubl ? '-0.6em' : '0.35em')
          .attr('fill', textCol).attr('font-size', r > 35 ? 10.5 : 10)
          .attr('font-weight', 600).attr('font-family', 'Inter, sans-serif')
          .text(n.label);

        // Label line 2
        if (hasSubl) {
          g.append('text')
            .attr('text-anchor', 'middle').attr('dy', '0.75em')
            .attr('fill', textSecCol).attr('font-size', 8.5)
            .attr('font-family', 'Inter, sans-serif').text(n.sublabel);
        }

        // Criticality badge
        var badgeR = 9;
        var bx = r * 0.68, by = -r * 0.68;
        g.append('circle').attr('cx', bx).attr('cy', by).attr('r', badgeR)
          .attr('fill', col).attr('opacity', 0.95);
        g.append('text').attr('x', bx).attr('y', by)
          .attr('text-anchor', 'middle').attr('dy', '0.35em')
          .attr('fill', 'white').attr('font-size', 7.5).attr('font-weight', 700)
          .attr('font-family', 'Inter, sans-serif').text(n.criticality);

        // Hover interaction
        g.on('mouseover', function(event) {
          d3.select(this).select('circle').transition().duration(150).attr('opacity', isDark ? 0.3 : 0.2);
          showTooltip(event, n, col);
        }).on('mousemove', function(event) {
          moveTooltip(event);
        }).on('mouseout', function() {
          d3.select(this).select('circle').transition().duration(150).attr('opacity', isDark ? 0.12 : 0.08);
          hideTooltip();
        }).on('focus', function(event) {
          showTooltip(event, n, col);
        }).on('blur', function() { hideTooltip(); });
      });

      // Feedback loop annotation
      svg.append('text')
        .attr('x', VW / 2).attr('y', VH - 8)
        .attr('text-anchor', 'middle')
        .attr('fill', isDark ? 'rgba(245,158,11,0.55)' : 'rgba(217,119,6,0.6)')
        .attr('font-size', 9.5).attr('font-weight', 500).attr('font-family', 'Inter, sans-serif')
        .attr('letter-spacing', '0.05em')
        .text('⟳  CLOSED-LOOP FEEDBACK · Monitoring → Data Platform (data quality alerts) · Monitoring → Training Cluster (retrain trigger)');
    }

    // === TOOLTIP ===
    var ttEl = document.getElementById('tooltip');
    function showTooltip(event, n, col) {
      if (!ttEl) return;
      var chips = n.subs.map(function(s) { return '<span class="tooltip-chip">' + s + '</span>'; }).join('');
      ttEl.innerHTML = '<div class="tooltip-name" style="color:' + col + '">' + n.label + (n.sublabel ? ' ' + n.sublabel : '') + '</div>' +
        '<div class="tooltip-row"><span class="tooltip-label">Layer</span><span class="tooltip-value">' + n.layer + '</span></div>' +
        '<div class="tooltip-row"><span class="tooltip-label">Criticality</span><span class="tooltip-value">' + n.criticality + ' / 10</span></div>' +
        '<div class="tooltip-chips">' + chips + '</div>';
      moveTooltip(event);
      ttEl.classList.add('visible');
    }
    function moveTooltip(event) {
      if (!ttEl) return;
      var x = event.clientX + 16, y = event.clientY - 20;
      if (x + 270 > window.innerWidth) x = event.clientX - 270;
      if (y + 160 > window.innerHeight) y = event.clientY - 160;
      ttEl.style.left = x + 'px'; ttEl.style.top = y + 'px';
    }
    function hideTooltip() { if (ttEl) ttEl.classList.remove('visible'); }

    // === INIT ===
    window.addEventListener('load', function() {
      buildDiagram();
    });
  </script>
